     */
    async connectWebSocket() {
        return new Promise((resolve, reject) => {
            this.ws = new WebSocket(`${config.microapexmarket.wsUrl}?apiKey=${config.microapexmarket.apiKey}`);

            this.ws.on('open', () => {
                this.isConnected = true;
